{
  "findings": [
    {
      "check_id": "CKV_AZURE_67",
      "title": "Ensure that 'HTTP Version' is the latest, if used to run the Function app",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The HTTP version is not explicitly set, which may result in the use of an outdated version. Using the latest HTTP version improves performance and security."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Ensure that Function apps is only accessible over HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The 'https_only' setting is not enabled, which means the Function App could be accessed over unencrypted HTTP, exposing it to potential interception."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "Authentication is not enabled for the Function App, which could allow unauthorized access to the application."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n\n  https_only = true\n\n  site_config {\n    http2_enabled = true\n  }\n\n  auth_settings {\n    enabled = true\n  }\n}",
  "fix_summary": "Enabled HTTPS-only access by setting 'https_only' to true. Configured the latest HTTP version by enabling HTTP/2 in 'site_config'. Enabled authentication by adding 'auth_settings' with 'enabled' set to true."
}
